const BASE='http://localhost:5173';
let seen=new Set();
async function walk(url, parent){
  if(seen.has(url))return; seen.add(url);
  let text; try{ text=await (await fetch(BASE+url,{signal:AbortSignal.timeout(20000)})).text(); }catch(e){ return; }
